public class Main {
    static int countCells(int rows, int cols) {
        int count = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) count++;
        }
        return count;
    }
    public static void main(String[] args) throws Exception {
        System.out.println(countCells(2, 3));
    }
}

